<script>
(function(){
  var _cs = document.currentScript;
  var NS = "http://www.w3.org/2000/svg";
  var FONT = "-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif";
  function el(tag, attrs, txt){
    var e = document.createElementNS(NS, tag);
    for (var k in attrs) e.setAttribute(k, attrs[k]);
    if (txt !== undefined) e.textContent = txt;
    return e;
  }
  function tx(x, y, s, anchor, size, fill, weight){
    return el("text", {x: x, y: y, "text-anchor": anchor, "font-size": size, "font-weight": weight || 400, fill: fill, "font-family": FONT}, s);
  }
  var svg = document.createElementNS(NS, "svg");
  svg.setAttribute("viewBox","0 0 680 300");
  svg.setAttribute("width","100%");
  var data = [{c:"Whitehorse",v:6.1},{c:"Charlottetown",v:5.6},{c:"Halifax",v:5.4},{c:"Saint John",v:4.8},{c:"Yellowknife",v:4.7},{c:"St. John’s",v:4.6},{c:"Winnipeg",v:4.2},{c:"Edmonton",v:3.5},{c:"Regina",v:3.4},{c:"Calgary",v:3.4},{c:"Victoria",v:3.4},{c:"Québec",v:3.3},{c:"Saskatoon",v:3.1},{c:"Montréal",v:3.0},{c:"Ottawa",v:3.0},{c:"Vancouver",v:3.0},{c:"Iqaluit",v:3.0},{c:"Thunder Bay",v:2.8},{c:"Toronto",v:2.1}];
  var NAT = 3.1, TARGET = 2.0;
  var margin = {left: 110, right: 24, top: 18, bottom: 46};
  var W = 680, H = 300;
  var PW = W - margin.left - margin.right;
  var PH = H - margin.top - margin.bottom;
  var n = data.length;
  var pitch = PH / n;
  var vals = data.map(function(d){ return d.v; });
  var lo = Math.floor((Math.min.apply(null, vals) - 0.4) * 2) / 2;
  var hi = Math.ceil((Math.max.apply(null, vals) + 0.4) * 2) / 2;
  function xp(v){ return margin.left + (v - lo) / (hi - lo) * PW; }
  function yp(i){ return margin.top + (i + 0.5) * pitch; }
  var plotL = margin.left, plotR = margin.left + PW, plotT = margin.top, plotB = margin.top + PH;

  // 1. gridlines: vertical ticks and faint row guides
  for (var t = Math.ceil(lo); t <= Math.floor(hi); t++){
    svg.appendChild(el("line", {x1: xp(t), x2: xp(t), y1: plotT, y2: plotB, stroke: "#ececec", "stroke-width": 0.5}));
  }
  for (var i = 0; i < n; i++){
    svg.appendChild(el("line", {x1: plotL, x2: plotR - 40, y1: yp(i), y2: yp(i), stroke: "#ececec", "stroke-width": 0.5, "stroke-dasharray": "1,3"}));
  }

  // 2. reference lines
  svg.appendChild(el("line", {x1: xp(TARGET), x2: xp(TARGET), y1: plotT - 2, y2: plotB, stroke: "#7a3030", "stroke-width": 1, "stroke-dasharray": "3,3"}));
  svg.appendChild(el("line", {x1: xp(NAT), x2: xp(NAT), y1: plotT - 2, y2: plotB, stroke: "#2e7d32", "stroke-width": 1, "stroke-dasharray": "3,3"}));

  // 4. axis lines (before dots so the dots paint on top)
  svg.appendChild(el("line", {x1: plotL, x2: plotR, y1: plotB, y2: plotB, stroke: "#d8d8d8", "stroke-width": 1}));
  svg.appendChild(el("line", {x1: plotL, x2: plotL, y1: plotT, y2: plotB, stroke: "#d8d8d8", "stroke-width": 1}));

  // 5. data dots
  for (var j = 0; j < n; j++){
    svg.appendChild(el("circle", {cx: xp(data[j].v), cy: yp(j), r: 3.5, fill: data[j].v > NAT ? "#8a3030" : "#4a5568"}));
  }

  // 6. gold pill on the highest city, left of the endpoint, dot stays at the data point
  var pillText = data[0].v.toFixed(1).replace(".", ",") + "\u00a0%";
  var pillW = Math.ceil(pillText.length * 9 * 0.58) + 10;
  var pillH = 16;
  var lastX = xp(data[0].v), lastY = yp(0);
  var pillX = lastX - pillW - 6;
  var pillY = lastY - pillH / 2;
  if (pillX < plotL) pillX = plotL;
  svg.appendChild(el("rect", {x: pillX, y: pillY, width: pillW, height: pillH, rx: 3, fill: "#e8a825"}));
  svg.appendChild(tx(pillX + pillW / 2, pillY + pillH / 2 + 3, pillText, "middle", 9, "#111111", 700));

  // 7. labels and annotations
  for (var r = 0; r < n; r++){
    svg.appendChild(tx(margin.left - 5, yp(r) + 3, data[r].c, "end", 8.5, "#aaaaaa", 400));
    if (r !== 0) svg.appendChild(tx(plotR - 4, yp(r) + 3, data[r].v.toFixed(1).replace(".", ",") + "\u00a0%", "end", 8.5, "#444444", 400));
  }
  for (var k = Math.ceil(lo); k <= Math.floor(hi); k++){
    svg.appendChild(tx(xp(k), plotB + 14, k.toFixed(1).replace(".", ",") + "\u00a0%", "middle", 8, "#999999", 400));
  }
  svg.appendChild(tx(margin.left + PW / 2, plotB + 30, "Variation annuelle de l’IPC, septembre 2026", "middle", 8, "#999999", 400));
  svg.appendChild(tx(xp(TARGET) + 4, plotT - 6, "CIBLE DE 2\u00a0%", "start", 7, "#7a3030", 700));
  svg.appendChild(tx(xp(NAT) + 4, plotT - 6, "CANADA 3,1\u00a0%", "start", 7, "#2e7d32", 700));

  // annotation block, right-anchored, clear of every dot (all rows below 4.0 sit left of mid-plot)
  var note = ["Écart de 4,0 points", "Toronto-Whitehorse,", "le double de la", "plage BdC 1 à 3\u00a0%"];
  var noteX = plotR - 40;
  var noteY = yp(11);
  var noteW = 86;
  svg.appendChild(el("rect", {x: noteX - noteW - 4, y: noteY - 9, width: noteW + 8, height: note.length * 10 + 2, fill: "#ffffff"}));
  for (var q = 0; q < note.length; q++){
    svg.appendChild(tx(noteX, noteY + q * 10, note[q], "end", 8, "#444444", 400));
  }

  // legend, derived from one base x and flush with the plot boundary
  var legend = [{t: "≤ NATIONAL", c: "#4a5568"}, {t: "> NATIONAL", c: "#8a3030"}];
  var lgx = plotR - 4;
  var lgy = plotT - 9;
  legend.forEach(function(it){
    var w = Math.ceil(it.t.length * 7.5 * 0.68);
    svg.appendChild(tx(lgx, lgy + 3, it.t, "end", 7.5, "#444444", 700));
    var cxl = lgx - w - 8;
    svg.appendChild(el("circle", {cx: cxl, cy: lgy, r: 3.5, fill: it.c}));
    lgx = cxl - 16;
  });

  _cs.parentNode.appendChild(svg);
})();
</script>
</div>
<div style="font-family:-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif;font-size:10px;color:#999;padding:4px 14px 10px;font-style:italic;">Source&nbsp;: Statistique Canada, Indice des prix à la consommation, septembre 2026, publié le 19 octobre 2026, via La Presse canadienne. &nbsp;|&nbsp; hdq.ca</div>
</div>
</div>
<p style="font-size:11px;color:#666;font-family:-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif;margin-top:6px;">Douze des 19 villes visées ont affiché un taux supérieur au taux national, et Statistique Canada a indiqué que la hausse du mazout a pesé plus lourd dans le Canada atlantique, où ce combustible est plus répandu. Statistique Canada a prévenu que les données par ville reposent sur de petits échantillons et peuvent fluctuer fortement.</p>
<p>Le mazout explique une partie de l’écart. Hors énergie, l’inflation était la plus élevée en Nouvelle-Écosse, à 3,3&nbsp;%, contre 2,1&nbsp;% à l’échelle nationale, et Statistique Canada a indiqué que la hausse du mazout avait eu une incidence plus marquée dans le Canada atlantique. Halifax, à 5,4&nbsp;%, ainsi que Charlottetown et Summerside, à 5,6&nbsp;%, vivent une inflation différente de celle de Toronto, à 2,1&nbsp;%.</p>
<p>Les données par ville reposent sur de petits échantillons, et chaque lecture isolée appelle donc à la prudence. La direction reste toutefois l’essentiel&nbsp;: un ménage de Halifax et un ménage de Toronto ne lisent pas la même inflation, et pourtant les deux sont interrogés au sujet de la même cible nationale.</p>
<h2>Pourquoi l’attente compte plus que le chiffre publié</h2>
<p>Un chiffre d’inflation isolé appartient au passé. Une attente est une prévision à partir de laquelle les gens agissent, et elle alimente les demandes salariales et les décisions de fixation des prix, ce qui explique pourquoi la Banque du Canada la suit de près. Environ la moitié des entreprises interrogées dans son Enquête sur les perspectives des entreprises prévoient de continuer à répercuter sur leur clientèle tout ou partie de la hausse de leurs coûts.</p>
<p>Les marchés ont réagi selon cette logique en quelques jours. Le 19 octobre, les swaps indexés sur le taux à un jour accordaient 87&nbsp;% de probabilité à une hausse d’un quart de point de la Banque du Canada le 28 octobre, selon des données de Bloomberg citées par le Financial Post, contre environ 30&nbsp;% une semaine plus tôt. Le gouverneur Tiff Macklem avait dit aux journalistes le 17 octobre qu’il s’attendait à ce que la Banque révise à la hausse sa prévision d’inflation, le pétrole se situant bien au-dessus du niveau supposé en juillet.</p>
<p>Le marché du travail complique le tableau. Le Canada a perdu 68&nbsp;000 emplois en septembre, un deuxième recul mensuel consécutif, et le taux de chômage est monté à 6,5&nbsp;%. Les ménages confrontés à des coûts de carburant plus élevés et à un marché du travail moins sûr n’ont pas tort de sentir la pression. La question comportementale est de savoir à quel signal ils accordent le plus de poids quand vient le moment de décider quoi faire de leur épargne.</p>
<h2>La saillance s’estompe lentement, et le 28 octobre est le prochain test</h2>
<p>Si l’expérience vécue est surpondérée, comme l’ont constaté Malmendier et Nagel, les attentes formées durant une année d’inflation de l’essence de 27,8&nbsp;% ont peu de chances de se réinitialiser dès que le prix à la pompe fléchira. L’écart se résorbe de l’une de deux façons&nbsp;: les attentes des ménages glissent vers les mesures fondamentales de 1,8&nbsp;% à 1,9&nbsp;%, ou l’inflation fondamentale glisse vers ce que les ménages anticipent déjà.</p>
<p>La Banque du Canada annoncera sa décision sur le taux directeur le 28 octobre, en même temps que la publication d’un Rapport sur la politique monétaire complet. Sa prévision d’inflation mise à jour montrera comment la banque centrale interprète l’écart, le taux directeur étant maintenu à 2,25&nbsp;% depuis octobre 2025.</p>',
  '<div class="toolkit-section">
<div class="toolkit-section-label">Ce qu’ils ressentent</div>
<p>Les clients voient dans la pompe et le reçu d’épicerie la preuve que l’inflation n’a pas été vaincue, et les discussions sur une hausse de taux de la Banque du Canada ont ajouté une deuxième inquiétude en toile de fond&nbsp;: celle de voir les coûts d’emprunt remonter. Ce qu’ils ressentent, c’est une perte de maîtrise des coûts du quotidien, non un avis sur le panier de l’IPC. Les clients qui renouvellent leur prêt hypothécaire d’ici un an le ressentent le plus vivement. Ceux du Canada atlantique n’ont pas tort, puisque leur inflation locale dépasse nettement le taux national.</p>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Quoi dire</div>
<div class="script-box">Je comprends pourquoi le prix à la pompe donne l’impression que l’inflation échappe à tout le monde. C’est une réaction légitime, parce que l’essence coûte réellement 27,8&nbsp;% de plus qu’il y a un an et que vous voyez ce chiffre chaque semaine. Voici ce que je vous propose de mettre en parallèle. Sans l’essence, les prix ont augmenté de 2,2&nbsp;%, et les deux mesures auxquelles la Banque du Canada se fie le plus pour l’inflation fondamentale sont toutes deux ressorties sous 2&nbsp;%. Les deux affirmations sont vraies en même temps. La Banque rendra sa prochaine décision sur les taux le 28 octobre, et une hausse est possible. Je préfère donc que nous regardions où un changement de taux toucherait réellement votre plan plutôt que de réagir à un titre. Votre plan a été conçu pour traverser des années où l’inflation se situe au-dessus et en dessous de la cible, et rien dans les dernières données ne change vos chiffres à long terme. Examinons les deux endroits où l’inflation pourrait réellement vous atteindre, le renouvellement de votre prêt hypothécaire et vos retraits, et décidons ensemble si quelque chose doit changer.</div>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Qui est touché</div>
<p><strong>Forte incidence&nbsp;:</strong> Les retraités et les personnes sur le point de prendre leur retraite qui tirent un revenu de leur portefeuille, qui ont tendance à se fier aux prix à la pompe et à l’épicerie et pourraient vouloir augmenter leurs liquidités ou abandonner leurs hypothèses à long terme, ainsi que les clients dont le prêt hypothécaire vient à échéance d’ici 12 mois et qui sont exposés à une hausse possible le 28 octobre.</p>
<p><strong>Incidence variable&nbsp;:</strong> Les clients du Canada atlantique et des territoires, où les taux locaux de 5,4&nbsp;% à Halifax, de 5,6&nbsp;% à Charlottetown et à Summerside et de 6,1&nbsp;% à Whitehorse justifient davantage l’inquiétude que ne le fait le chiffre national. Ils ont besoin d’être entendus avant de recevoir des données.</p>
<p><strong>Avantage potentiel&nbsp;:</strong> Les clients qui détiennent des titres énergétiques canadiens et les épargnants détenant des dépôts à court terme, dont les taux seraient révisés à la hausse si la Banque relevait ses taux.</p>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Liste de vérification</div>
<div class="checklist-item">Sortir la liste de tous les clients dont le prêt hypothécaire vient à échéance d’ici 12 mois et inscrire la date de renouvellement à côté de la décision du 28 octobre.</div>
<div class="checklist-item">Repérer les clients du Canada atlantique et des territoires et amorcer chaque appel par leur chiffre d’inflation local avant le chiffre national.</div>
<div class="checklist-item">Comparer l’hypothèse d’inflation de chaque plan de retraité aux mesures fondamentales de 1,8&nbsp;% et de 1,9&nbsp;% et aux attentes des consommateurs de 3,91&nbsp;%, et consigner laquelle le plan retient.</div>
<div class="checklist-item">Noter tout client qui a demandé de modifier sa répartition en raison du prix du carburant ou de l’épicerie, et documenter la conversation.</div>
<div class="checklist-item">Préparer un résumé en une ligne de l’inflation globale (3,1&nbsp;%), hors essence (2,2&nbsp;%) et fondamentale (1,8&nbsp;% à 1,9&nbsp;%) à envoyer après chaque appel.</div>
<div class="checklist-item">Inscrire au calendrier le 28 octobre pour la décision de la Banque du Canada et le Rapport sur la politique monétaire, et fixer des appels de suivi pour l’après-midi même.</div>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Modèle de courriel de suivi</div>
<div class="email-box" id="respond-email">
<strong>Objet&nbsp;:</strong> L’inflation, la pompe et votre plan<br><br>
Bonjour [Nom du client],<br><br>
Merci d’avoir pris le temps de discuter des chiffres de l’inflation avec moi aujourd’hui. Comme promis, voici la version courte.<br><br>
L’essence coûte 27,8&nbsp;% de plus qu’il y a un an, ce qui explique que les prix paraissent si élevés. Sans l’essence, les prix ont augmenté de 2,2&nbsp;% en septembre, et les mesures de l’inflation fondamentale de la Banque du Canada se sont établies à 1,8&nbsp;% et à 1,9&nbsp;%. Les deux constats sont fondés, et ils vont dans des directions opposées.<br><br>
La Banque du Canada annoncera sa prochaine décision sur les taux le 28 octobre. Une hausse est possible. Je passerai donc en revue tout renouvellement hypothécaire ou projet d’emprunt qui pourrait être touché, et je communiquerai avec vous l’après-midi même.<br><br>
Votre plan à long terme a été conçu pour résister à des années où l’inflation se situe tant au-dessus qu’en dessous de la cible. Si quoi que ce soit a changé dans votre situation, dites-le-moi et nous ajusterons de façon réfléchie plutôt que de réagir à un titre.<br><br>
[Votre nom]<br><br>
<em>La présente communication est fournie à des fins éducatives seulement et ne constitue pas un conseil en placement personnalisé.</em>
</div>
<button class="btn-copy" onclick="copyEmail(''respond-email'', this)">Copier le courriel</button>
</div>',
  '<div class="toolkit-section">
<div class="toolkit-section-label">Profils de clients à cibler</div>
<p><strong>Investisseurs autonomes qui se sont réfugiés dans les liquidités, les CPG ou l’or depuis la flambée de l’essence&nbsp;:</strong> ils réagissent au prix le plus visible sans cadre pour comprendre l’écart entre 27,8&nbsp;% à la pompe et 1,9&nbsp;% d’inflation fondamentale.</p>
<p><strong>Propriétaires avec une dette à taux variable ou un renouvellement d’ici 12 mois&nbsp;:</strong> les swaps indexés sur le taux à un jour accordaient le 19 octobre 87&nbsp;% de probabilité à une hausse de la Banque du Canada, et peu de gens ont simulé l’effet sur leur versement.</p>
<p><strong>Résidents du Canada atlantique et des territoires&nbsp;:</strong> l’inflation locale va de 4,6&nbsp;% à St. John’s à 6,1&nbsp;% à Whitehorse, de sorte que l’inquiétude est justifiée et que le besoin d’un plan est réel.</p>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Phrase d’accroche</div>
<div class="script-box">Les chiffres de l’inflation sont sortis lundi et l’essence a presque augmenté de 28&nbsp;% sur un an, mais les mesures fondamentales que surveille la Banque du Canada ont en fait reculé. J’appelle des personnes qui gèrent elles-mêmes leurs placements pour savoir comment elles interprètent cet écart et si cela a changé quoi que ce soit dans leur portefeuille.</div>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Proposition de valeur</div>
<p>Les investisseurs autonomes élaborent leurs prévisions d’inflation à partir du prix le plus visible de l’économie, ce qui correspond exactement à la façon dont, selon Tversky et Kahneman en 1973, les gens jugent la fréquence quand les exemples sont frappants. Personne n’est en position de distinguer pour eux la pompe du panier, et le risque se manifeste dans leurs décisions&nbsp;: vendre pour se réfugier dans les liquidités au mauvais moment, ou détenir des couvertures contre l’inflation dimensionnées en fonction d’une crainte plutôt que d’une prévision.</p>
<p>Un conseiller offre un cadre qui existe avant le titre de l’actualité&nbsp;: quelle inflation compte pour ce ménage, sur quel horizon et à quel coût si l’hypothèse est fausse. Une hausse de taux possible le 28 octobre, avec un Rapport sur la politique monétaire le même jour, fournit une raison naturelle de demander un entretien.</p>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Questions de découverte</div>
<div class="checklist-item">Comment interprétez-vous les chiffres de l’inflation publiés lundi&nbsp;?</div>
<div class="checklist-item">Quand vous pensez aux prix au cours des cinq prochaines années, quel chiffre avez-vous en tête, et sur quoi repose-t-il&nbsp;?</div>
<div class="checklist-item">Quelque chose a-t-il changé dans la façon dont votre argent est investi depuis que le prix de l’essence a commencé à monter&nbsp;?</div>
<div class="checklist-item">À qui parlez-vous quand un titre vous donne envie de modifier votre portefeuille&nbsp;?</div>
<div class="checklist-item">Avez-vous un prêt hypothécaire, une marge de crédit ou un renouvellement à venir sur lesquels une hausse de taux le 28 octobre aurait une incidence&nbsp;?</div>
<div class="checklist-item">Si vos placements perdaient 10&nbsp;% le trimestre prochain, que feriez-vous, et ce plan est-il consigné par écrit&nbsp;?</div>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Modèle de courriel de prospection</div>
<div class="email-box" id="prospect-email">
<strong>Objet&nbsp;:</strong> L’écart entre la pompe et le panier<br><br>
Bonjour [Nom du client potentiel],<br><br>
L’essence coûte 27,8&nbsp;% de plus qu’il y a un an, et pourtant les mesures d’inflation auxquelles la Banque du Canada se fie le plus pour les prix de fond ont reculé à 1,8&nbsp;% et à 1,9&nbsp;% en septembre. Les consommateurs prévoient maintenant une inflation de 3,91&nbsp;% sur cinq ans dans la dernière enquête de la Banque du Canada. C’est dans l’écart entre ce qui est mesuré et ce qui est attendu que les décisions de placement déraillent souvent.<br><br>
À l’approche de la décision de la Banque du Canada sur les taux le 28 octobre, je vous propose un bref appel pour comparer ce que ces chiffres signifient pour votre portefeuille et vos emprunts. Un entretien de 20 minutes cette semaine vous serait-il utile&nbsp;?<br><br>
[Votre nom]<br><br>
<em>La présente communication est fournie à des fins éducatives seulement et ne constitue pas un conseil en placement personnalisé.</em>
</div>
<button class="btn-copy" onclick="copyEmail(''prospect-email'', this)">Copier le courriel</button>
</div>',
  '[{"value":"27,8 %","label":"Essence, variation annuelle"},{"value":"1,9 %","label":"IPC-méd, septembre"},{"value":"3,91 %","label":"Attentes à cinq ans, consommateurs"},{"value":"4,0 pts","label":"Écart des villes, Toronto-Whitehorse"}]',
  'behaviour-139.jpg',
  'Les ménages canadiens mettent en balance une hausse annuelle de 27,8 % des prix de l’essence et des mesures d’inflation fondamentale revenues sous 2 %. La recherche comportementale sur l’heuristique de disponibilité aide à comprendre pourquoi les deux lectures semblent si différentes. Photo : iStock.',
  5,
  '2026-10-22T08:00:00',
