  var d = "";
  for (var i = 0; i < px.length; i++) d += (i ? "L" : "M") + xp(px[i][0]) + "," + yp(px[i][1]);
  svg.appendChild(el("path", {d: d, fill: "none", stroke: "#4a5568", "stroke-width": 2}));
  // 4. axis lines
  svg.appendChild(el("line", {x1: plotL, x2: plotR, y1: plotB, y2: plotB, stroke: "#d8d8d8", "stroke-width": 1}));
  svg.appendChild(el("line", {x1: plotL, x2: plotL, y1: plotT, y2: plotB, stroke: "#d8d8d8", "stroke-width": 1}));
  // 5. dots: period low and endpoint
  var low = px[15];
  svg.appendChild(el("circle", {cx: xp(low[0]), cy: yp(low[1]), r: 3.5, fill: "#4a5568"}));
  var last = px[px.length - 1];
  var lx = xp(last[0]), ly = yp(last[1]);
  svg.appendChild(el("circle", {cx: lx, cy: ly, r: 4, fill: "#4a5568"}));
  // 6. gold pill left of the endpoint
  var pillText = fmt(last[1]);
  var pillW = Math.ceil(pillText.length * 9 * 0.58) + 10;
  var pillH = 16;
  var pillX = lx - pillW - 6;
  var pillY = ly - pillH / 2;
  svg.appendChild(el("rect", {x: pillX, y: pillY, width: pillW, height: pillH, rx: 3, fill: "#e8a825"}));
  svg.appendChild(tx(pillX + pillW / 2, pillY + pillH / 2 + 3, pillText, "middle", 9, "#111111", 700));
  // 7. labels
  for (var a = 35000; a <= 37000; a += 500){
    svg.appendChild(tx(plotL - 6, yp(a) + 3, fmt(a), "end", 8.5, "#aaaaaa", 400));
  }
  var xt = [["2026-09-21","21 sept."],["2026-09-28","28 sept."],["2026-10-05","5 oct."],["2026-10-12","12 oct."],["2026-10-19","19 oct."]];
  xt.forEach(function(t){ svg.appendChild(tx(xp(t[0]), plotB + 14, t[1], "middle", 8, "#999999", 400)); });
  svg.appendChild(tx(plotL + 8, yp(record) - 5, "RECORD D’AOÛT " + record.toFixed(2).replace(/\B(?=(\d{3})+(?!\d))/g, " ").replace(".", ","), "start", 7.5, "#1a3560", 700));
  svg.appendChild(tx(xp(low[0]), yp(low[1]) + 14, "CREUX 7 OCT. " + fmt(low[1]), "middle", 7.5, "#444444", 700));
  var evLabel = "19 OCT. HAUSSE PROB.";
  var evW = Math.ceil(evLabel.length * 7 * 0.68);
  var nearRight = (evX + evW + 3) > plotR;
  svg.appendChild(tx(nearRight ? evX - 4 : evX + 4, plotB - 8, evLabel, nearRight ? "end" : "start", 7, "#c0392b", 700));
  svg.appendChild(tx(plotL + 8, plotB - 8, "INDICE COMPOSÉ S&P/TSX", "start", 7.5, "#888888", 400));
  svg.appendChild(tx(margin.left + PW / 2, plotB + 30, "Clôtures, 16 septembre au 21 octobre 2026", "middle", 8, "#999999", 400));
  _cs.parentNode.appendChild(svg);
})();
</script>
